import {esc} from './text.js';
import {printBookHTML,trimOf,designOf,localeOf} from './book.js';
export function proofDocument(p,page){const [w,h]=trimOf(p),d=designOf(p),inner=Math.max(.5,w-d.margin*2),height=Math.max(.5,h-d.margin*2);const fonts=[['Lora','lora.ttf'],['DM Sans','dm-sans.ttf'],['Literata','literata.ttf'],['SourceSerif','source-serif.ttf'],['IBMPlex','ibm-plex.ttf']].map(([name,file])=>`@font-face{font-family:'${name}';src:url('${new URL('assets/'+file,import.meta.url).href}');font-display:block}`).join('');const style=`${fonts}html{overflow:hidden}.single-proof{width:${w}in;height:${h}in;overflow:hidden;background:white}.single-proof .book-page{width:${inner}in;height:${height}in;min-height:0;margin:${d.margin}in;padding:0;column-width:${inner}in;column-gap:${d.margin*2}in;column-fill:auto;overflow:visible}.single-proof .chapter-page{padding:0}.single-proof .book-page>div,.single-proof .book-page>p{max-width:100%}.single-proof .title-leaf,.single-proof .half-title,.single-proof .copyright-leaf{min-height:${height-.03}in}.single-proof p{overflow-wrap:anywhere}.single-proof .book-page:empty::before{content:' '}`;return printBookHTML(p,{page}).replace('</style>',style+'</style>').replace('<body class="single-proof">',`<body class="single-proof" data-proof-section="${esc(page)}">`);}
export function proofPageCount(scrollWidth,width,margin){return Math.max(1,Math.ceil((scrollWidth+margin*2*96-.5)/(width*96)));}
export function moveProofColumn(section,index,p){const [width]=trimOf(p),dir=localeOf(p).dir==='rtl'?1:-1;section.style.transform=`translateX(${dir*index*width*96}px)`;}
